import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Card, Button, Container, Row, Col } from 'react-bootstrap';
import './EventList.css'; // Import custom CSS for hover effect

const EventList = () => {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const token = localStorage.getItem('authToken');
        const response = await axios.get('/api/events/available', {
          headers: { Authorization: `Bearer ${token}` },
        });
        setEvents(response.data);
      } catch (error) {
        console.error('Error fetching events:', error);
      }
    };

    fetchEvents();
  }, []);

  return (
    <Container className="mt-4">
      <h2 className="text-center mb-4">Available Events</h2>
      <Row>
        {events.map(event => (
          <Col key={event._id} md={4} className="mb-4">
            <Card className="event-card">
              <div className="image-container">
                <Card.Img variant="top" src={event.image || '/default-event.jpg'} alt={event.title} />
                <div className="overlay">
                  <Card.Body>
                    <Card.Title>{event.title}</Card.Title>
                    <Card.Text>
                      {event.description}
                      <br />
                      <strong>Date:</strong> {new Date(event.date).toLocaleDateString()}
                      <br />
                      <strong>Registrants:</strong> {event.totalRegistrants}
                    </Card.Text>
                    <Button variant="primary">Register</Button>
                  </Card.Body>
                </div>
              </div>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default EventList;
